import {filterGames,cumulativeStats} from './services.js';
import {escapeHTML as esc} from './config.js';
export const comparisonMetrics=[['공격','시도','P'],['공격','득점','Q'],['공격','범실','S'],['공격','성공률','T',true],['공격','효율','V',true],['리시브','시도','B'],['리시브','성공','C'],['리시브','정확','D'],['리시브','실패','E'],['리시브','효율','F',true],['서브','시도','AC'],['서브','에이스','AF'],['서브','실패','AG'],['서브','효율','AI',true],['서브','위협도','AJ',true],['블로킹','득점','Z'],['블로킹','유효','AA'],['수비','디그 성공','H'],['수비','디그 실패','I'],['수비','디그 성공률','N',true],['이단연결','시도','AK'],['이단연결','성공','AN'],['이단연결','실패','AP']];
const fmt=(v,pct=false)=>v===null||v===undefined?'−':Number(v).toLocaleString('ko-KR',{maximumFractionDigits:1})+(pct?'%':'');
export function analysisPage(content,db){const players=db.players.filter(p=>!p.deletedAt||db.games.some(g=>g.roster.some(r=>r.playerId===p.id)));if(!players.length){content.innerHTML='<div class="page-heading"><h1>전술 분석</h1></div><div class="empty">선수를 등록하고 종료 경기의 기록을 입력하면 분석할 수 있습니다.</div>';return;}
const options=selected=>players.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)} · ${esc(p.position)}${p.deletedAt?' (삭제된 선수)':''}</option>`).join('');content.innerHTML=`<div class="page-heading"><div><h1>전술 분석</h1><p>선수별 기록과 두 선수의 공격·수비 역할을 비교합니다.</p></div></div><div class="filters analysis-filters"><label>선수 A <select id="analysisA">${options(players[0].id)}</select></label><label>선수 B <select id="analysisB">${options(players[1]?.id||players[0].id)}</select></label><label>기간 <select id="analysisPeriod"><option value="all">전체</option><option value="year">올해</option><option value="recent">최근 10경기</option></select></label><label>기록 기준 <select id="analysisBasis"><option value="total">누적 기록</option><option value="set">세트당 기록</option></select></label></div><div id="analysisResult"></div>`;
const render=()=>{const games=filterGames(db.games,content.querySelector('#analysisPeriod').value),a=players.find(p=>p.id===content.querySelector('#analysisA').value),b=players.find(p=>p.id===content.querySelector('#analysisB').value),sa=cumulativeStats(games,a.id),sb=cumulativeStats(games,b.id),perSet=content.querySelector('#analysisBasis').value==='set';const value=(s,key,pct)=>pct?s.values[key]:perSet?(s.setCount?s.values[key]/s.setCount:null):s.values[key];
const profile=(p,s)=>`<section class="panel analysis-profile"><div class="panel-heading"><h2>${esc(p.name)} <span class="muted small">${esc(p.position)}</span></h2><a class="inline-link" href="#player/${p.id}">선수 상세</a></div><p>${s.games}경기 · ${s.setCount}세트</p><dl><dt>공격 점유율</dt><dd>${fmt(s.values.W,true)}</dd><dt>리시브 점유율</dt><dd>${fmt(s.values.G,true)}</dd><dt>공격 득점 / 세트</dt><dd>${fmt(s.setCount?s.values.Q/s.setCount:null)}</dd><dt>서브 에이스 / 세트</dt><dd>${fmt(s.setCount?s.values.AF/s.setCount:null)}</dd></dl>${!s.games?'<p class="muted">이 기간의 종료 경기 기록이 없습니다.</p>':''}</section>`;
content.querySelector('#analysisResult').innerHTML=`<div class="analysis-profiles">${profile(a,sa)}${profile(b,sb)}</div><p class="muted small">점유율은 선택 기간의 팀 전체 시도 대비 비중입니다. 세트 수는 점수가 입력된 세트의 명단 기준으로, 실제 출장 시간은 반영하지 않습니다. 기록 표본과 포지션을 함께 보며 판단하세요.</p>${a.id===b.id?'<p class="error">서로 다른 선수를 선택하면 비교할 수 있습니다.</p>':''}<section class="panel"><div class="panel-heading"><h2>선수 비교</h2><span class="muted small">${perSet?'세트당 기록':'누적 기록'} · 비율은 누적 원본으로 계산</span></div><div class="table-wrap"><table class="comparison-table"><thead><tr><th>분류</th><th>기록</th><th>${esc(a.name)}</th><th>${esc(b.name)}</th><th>A − B</th></tr></thead><tbody>${comparisonMetrics.map(([group,label,key,pct])=>{const av=value(sa,key,pct),bv=value(sb,key,pct),delta=av===null||bv===null?null:av-bv;return `<tr><td>${group}</td><td>${label}</td><td>${fmt(av,pct)}</td><td>${fmt(bv,pct)}</td><td>${delta===null?'−':(delta>0?'+':'')+fmt(delta)+(pct?'%p':'')}</td></tr>`}).join('')}</tbody></table></div></section><p class="muted small">차이는 우열 점수가 아닙니다. 범실·실패는 적을수록 유리하며 시도·점유율은 맡은 역할에 따라 달라집니다. 모든 비율은 기존 기록지 계산식을 사용합니다.</p>`;};content.querySelectorAll('select').forEach(el=>el.onchange=render);render();}
